int *spiralOrder(int **matrix, int matrixSize, int *matrixColSize, int *returnSize) {
  int rows = matrixSize, cols = matrixColSize[0];
  int *order = (int *)malloc(sizeof(int) * rows * cols);
  *returnSize = 0;
  int left = 0, right = cols - 1, top = 0, bottom = rows - 1;
  while (left <= right && top <= bottom) {
    for (int c = left; c <= right; c++) {
      order[(*returnSize)++] = matrix[top][c];
    }
    for (int r = top + 1; r <= bottom; r++) {
      order[(*returnSize)++] = matrix[r][right];
    }
    if (left < right && top < bottom) {
      for (int c = right - 1; c > left; c--) {
        order[(*returnSize)++] = matrix[bottom][c];
      }
      for (int r = bottom; r > top; r--) {
        order[(*returnSize)++] = matrix[r][left];
      }
    }
    left++;
    right--;
    top++;
    bottom--;
  }
  return order;
}

func spiralOrder(matrix [][]int) []int {
	if len(matrix) == 0 || len(matrix[0]) == 0 {
		return []int{}
	}
	rows, cols := len(matrix), len(matrix[0])
	order := []int{}
	left, right, top, bottom := 0, cols-1, 0, rows-1
	for left <= right && top <= bottom {
		for c := left; c <= right; c++ {
			order = append(order, matrix[top][c])
		}
		for r := top + 1; r <= bottom; r++ {
			order = append(order, matrix[r][right])
		}
		if left < right && top < bottom {
			for c := right - 1; c > left; c-- {
				order = append(order, matrix[bottom][c])
			}
			for r := bottom; r > top; r-- {
				order = append(order, matrix[r][left])
			}
		}
		left++
		right--
		top++
		bottom--
	}
	return order
}

class Solution {
  public List<Integer> spiralOrder(int[][] matrix) {
    List<Integer> order = new ArrayList<>();
    if (matrix.length == 0 || matrix[0].length == 0) {
      return order;
    }
    int rows = matrix.length, cols = matrix[0].length;
    int left = 0, right = cols - 1, top = 0, bottom = rows - 1;
    while (left <= right && top <= bottom) {
      for (int c = left; c <= right; c++) {
        order.add(matrix[top][c]);
      }
      for (int r = top + 1; r <= bottom; r++) {
        order.add(matrix[r][right]);
      }
      if (left < right && top < bottom) {
        for (int c = right - 1; c > left; c--) {
          order.add(matrix[bottom][c]);
        }
        for (int r = bottom; r > top; r--) {
          order.add(matrix[r][left]);
        }
      }
      left++;
      right--;
      top++;
      bottom--;
    }
    return order;
  }
}

class Solution:
    def spiralOrder(self, matrix: List[List[int]]) -> List[int]:
        if not matrix or not matrix[0]:
            return []
        rows, cols = len(matrix), len(matrix[0])
        order = []
        left, right, top, bottom = 0, cols - 1, 0, rows - 1
        while left <= right and top <= bottom:
            for c in range(left, right + 1):
                order.append(matrix[top][c])
            for r in range(top + 1, bottom + 1):
                order.append(matrix[r][right])
            if left < right and top < bottom:
                for c in range(right - 1, left, -1):
                    order.append(matrix[bottom][c])
                for r in range(bottom, top, -1):
                    order.append(matrix[r][left])
            left += 1
            right -= 1
            top += 1
            bottom -= 1
        return order

impl Solution {
  pub fn spiral_order(matrix: Vec<Vec<i32>>) -> Vec<i32> {
    let mut order = vec![];
    if matrix.is_empty() || matrix[0].is_empty() {
      return order;
    }
    let rows = matrix.len();
    let cols = matrix[0].len();
    let (mut left, mut right, mut top, mut bottom) = (0i32, cols as i32 - 1, 0i32, rows as i32 - 1);
    while left <= right && top <= bottom {
      for c in left..=right {
        order.push(matrix[top as usize][c as usize]);
      }
      for r in top + 1..=bottom {
        order.push(matrix[r as usize][right as usize]);
      }
      if left < right && top < bottom {
        for c in (left + 1..right).rev() {
          order.push(matrix[bottom as usize][c as usize]);
        }
        for r in (top + 1..=bottom).rev() {
          order.push(matrix[r as usize][left as usize]);
        }
      }
      left += 1;
      right -= 1;
      top += 1;
      bottom -= 1;
    }
    order
  }
}

const spiralOrder = (matrix: number[][]): number[] => {
  const order: number[] = [];
  if (matrix.length === 0 || matrix[0].length === 0) return order;
  const rows = matrix.length;
  const cols = matrix[0].length;
  let left = 0;
  let right = cols - 1;
  let top = 0;
  let bottom = rows - 1;
  while (left <= right && top <= bottom) {
    for (let c = left; c <= right; c++) order.push(matrix[top][c]);
    for (let r = top + 1; r <= bottom; r++) order.push(matrix[r][right]);
    if (left < right && top < bottom) {
      for (let c = right - 1; c > left; c--) order.push(matrix[bottom][c]);
      for (let r = bottom; r > top; r--) order.push(matrix[r][left]);
    }
    left++;
    right--;
    top++;
    bottom--;
  }
  return order;
};

class Solution {
public:
  vector<int> spiralOrder(vector<vector<int>> &matrix) {
    if (matrix.size() == 0 || matrix[0].size() == 0) {
      return {};
    }

    int rows = matrix.size(), columns = matrix[0].size();
    vector<int> order;
    int left = 0, right = columns - 1, top = 0, bottom = rows - 1;
    while (left <= right && top <= bottom) {
      for (int column = left; column <= right; column++) {
        order.push_back(matrix[top][column]);
      }
      for (int row = top + 1; row <= bottom; row++) {
        order.push_back(matrix[row][right]);
      }
      if (left < right && top < bottom) {
        for (int column = right - 1; column > left; column--) {
          order.push_back(matrix[bottom][column]);
        }
        for (int row = bottom; row > top; row--) {
          order.push_back(matrix[row][left]);
        }
      }
      left++;
      right--;
      top++;
      bottom--;
    }
    return order;
  }
};
